window.products.push({"id":309240,"name":"BIA Cordon Bleu 7-Ounce White Porcelain Cup and Saucer, Set of 4","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/31UeTWsLEhL._AC_.jpg","description":"Amazon.com When just a spot of tea won't do, this classic white porcelain cup and saucer set in French bistro style may be for you. Drink a generous serving of your favorite tea, coffee, or delicious cappuccino from large 7-ounce cups. Cups are fashioned in straight lines and sit on broad saucers. And there's no need for special treatment; both cups and saucers are microwave-, dishwasher-, and oven-safe. Ideal for everyday use or after-dinner guest service. --Matthew Evans","images":["https://m.media-amazon.com/images/I/31UeTWsLEhL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"BIA Cordon Bleu","source_asin":"B00004S4X4","category_path":"Home & Kitchen"},"sku":"BM-309240","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00004S4X4","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00004S4X4","price_pending":true,"merchant_ready":false});
